   143  bool TcpLayer::removeTcpOption(TcpOptionType optionType)
   144  {
   145          TcpOption opt = getTcpOption(optionType);
   146          if (opt.isNull())
   147          {
   148                  return false;
   149          }
   150
   151          // calculate total TCP option size
   152          TcpOption curOpt = getFirstTcpOption();
   153          size_t totalOptSize = 0;
   154          while (!curOpt.isNull())
   155          {
   156                  totalOptSize += curOpt.getTotalSize();
   157                  curOpt = getNextTcpOption(curOpt);
   158          }
   159          totalOptSize -= opt.getTotalSize();
   160
   161
   162          int offset = opt.getRecordBasePtr() - m_Data;
   163
   164          if (!shortenLayer(offset, opt.getTotalSize()))
   165          {
   166                  return false;
   167          }
   168
   169          adjustTcpOptionTrailer(totalOptSize);
   170
   171          m_OptionReader.changeTLVRecordCount(-1);
   172
   173          return true;
   174  }
